const niche = $('Edit Fields').first().json.niche || '';
 const raw = $('SerperAPI Google Search - Typography').first()?.json || {};
 const results = raw?.organic || raw?.organic_results || [];

 // Build per-doc word sets for IDF
 const docs = results.map(r =>
   ((r.title || '') + ' ' + (r.snippet || '')).toLowerCase()
   .split(/[\s\-\/,.|&()+]+/)
   .filter(w => w.length > 3 && /^[a-z]+$/.test(w))
 );

 // Word frequency across all docs (TF) and doc frequency (IDF)
 const tf = {}, df = {};
 docs.forEach(words => {
   const seen = new Set();
   words.forEach(w => {
     tf[w] = (tf[w] || 0) + 1;
     if (!seen.has(w)) { df[w] = (df[w] || 0) + 1; seen.add(w); }
   });
 });

 const n = docs.length || 1;
 // Words appearing in >80% of docs are stop words, <2 docs are noise
 const topWords = Object.entries(tf)
   .filter(([w]) => df[w] >= 2 && df[w] / n < 0.8)
   .map(([w, count]) => ({ w, score: count * Math.log(n / df[w]) }))
   .sort((a, b) => b.score - a.score)
   .slice(0, 30)
   .map(e => e.w);

 const phrases = results
   .map(r => r.title || '')
   .filter(Boolean)
   .map(title => title.replace(/\|.*$/, '').trim())
   .filter(t => t.length > 3 && t.length < 60)
   .slice(0, 12);

 return [{ json: {
   source: 'typography',
   niche,
   data: {
     topTypographyTerms: topWords,
     phrases,
     totalResults: results.length,
   }
 } }];

const triggerData = $('Execute Workflow Trigger').first().json || {};
const niche = triggerData.niche
  || (() => { try { return JSON.parse(triggerData.context || '{}').niche; } catch(_) { return ''; } })()
  || '';

const parseJSON = (str, fallback) => {
  try {
    const clean = str.replace(/```json|```/g, '').trim();
    const match = clean.match(/[\[{][\s\S]*[\]}]/);
    return JSON.parse(match?.[0] || str);
  } catch(_) { return fallback; }
};

const geminiText = $('Gemini Typography Analyst').first().json?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
const typography = parseJSON(geminiText, {});

const signalData = (() => {
  try { return $('Parse Typography Signals').first().json?.data || {}; } catch(_) { return {}; }
})();

return [{ json: {
  niche,
  typography: {
    dominantFontStyle: typography.dominantFontStyle || '',
    letteringMood:     typography.letteringMood     || '',
    textLayout:        typography.textLayout         || '',
    suggestedPhrases:  typography.suggestedPhrases   || [],
    typographyNotes:   typography.typographyNotes    || '',
    topTerms:          signalData.topTypographyTerms || [],
    phrases:           signalData.phrases            || [],
    totalResults:      signalData.totalResults       || 0,
  }
} }];

